 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B3_"));var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/layout.json"));var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).ToDictionary(m=>m.name);int placed=0,lights=0,off=0;Material Map(Material m)=>m&&m.name.StartsWith("B4O_")&&mats.TryGetValue("B3M_"+m.name.Substring(4),out var n)?n:m;
 foreach(var q in JArray.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/refine_additions.json"))){string n=(string)q["name"];if(root.GetComponentsInChildren<Transform>().Any(t=>t.name==n))throw new Exception("Already refined");var parent=root.transform.Find("B3_"+(string)q["room"]+"_Sector/Equipment");var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)q["asset"]),parent);go.name=n;go.transform.localPosition=V(q["position"]);go.transform.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);foreach(var c in go.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);var bc=go.AddComponent<BoxCollider>();bc.center=V(q["center"]);bc.size=V(q["size"]);foreach(var mr in go.GetComponentsInChildren<MeshRenderer>())mr.sharedMaterials=mr.sharedMaterials.Select(Map).ToArray();placed++;}
