 foreach(var room in plan["rooms"].Where(r=>(string)r["kind"]!="core")){string id=(string)room["id"];float rad=(float)room["r"];bool on=(bool)plan["circuits"].Single(c=>(string)c["room"]==id)["default_on"];var parent=root.transform.Find("B3_"+id+"_Sector/WorkLighting");var used=new List<float>();foreach(var q in plan["placements"].Where(q=>(string)q["room"]==id&&(string)q["role"]!="BenchAccessory")){var p=V(q["position"]);float a=Mathf.Atan2(p.z,p.x)*Mathf.Rad2Deg;if(used.Any(v=>Mathf.Abs(Mathf.DeltaAngle(v,a))<27))continue;used.Add(a);var dir=new Vector3(Mathf.Cos(a*Mathf.Deg2Rad),0,Mathf.Sin(a*Mathf.Deg2Rad));var loc=dir*(Mathf.Sqrt(rad*rad-3.3f*3.3f)-.20f)+Vector3.up*3.3f;var target=dir*(rad-2.5f)+Vector3.up*1.0f;var normal=(loc-target).normalized;var tangent=Vector3.Cross(Vector3.up,dir);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(A+"Environment/B4/BO_SealedTaskLight.fbx"),parent);g.name="B3_"+id+"_EquipmentWallLight_"+used.Count;g.transform.localPosition=loc;g.transform.localRotation=Quaternion.LookRotation(Vector3.Cross(tangent,normal),normal);foreach(var mr in g.GetComponentsInChildren<MeshRenderer>())mr.sharedMaterials=mr.sharedMaterials.Select(Map).ToArray();var child=new GameObject("LightSource");child.transform.SetParent(g.transform,false);child.transform.localPosition=new Vector3(0,-.06f,0);child.transform.localRotation=Quaternion.Euler(90,0,0);var l=child.AddComponent<Light>();l.type=LightType.Spot;l.color=new Color(.83f,.89f,.93f);l.intensity=2.5f;l.range=6.5f;l.spotAngle=100;l.innerSpotAngle=60;l.shadows=used.Count%2==0?LightShadows.Soft:LightShadows.None;l.shadowBias=.01f;l.shadowNormalBias=.015f;l.enabled=on;lights++;}if(!on)foreach(var mr in parent.GetComponentsInChildren<MeshRenderer>()){mr.sharedMaterials=mr.sharedMaterials.Select(m=>m&&m.name.Contains("Lamp")?lampOff:m).ToArray();off++;}}
 RenderSettings.ambientSkyColor=new Color(.23f,.255f,.28f);RenderSettings.ambientEquatorColor=new Color(.16f,.18f,.21f);RenderSettings.ambientGroundColor=new Color(.09f,.11f,.14f);foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{addedEquipment=placed,wallWorkLights=lights,offFixtureRenderers=off};File.WriteAllText(R+"/Docs/Review/2026-11-09_B3_FullFloor/refine.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object CCTVSurvey(){var p=AssetDatabase.LoadAssetAtPath<GameObject>(A+"Enemy/CCTV_SecurityCamera_Articulated.prefab");return p.GetComponentsInChildren<Transform>(true).Select(t=>new{t.name,position=t.localPosition.ToString(),euler=t.localEulerAngles.ToString(),components=t.GetComponents<Component>().Select(c=>c.GetType().Name),bounds=t.GetComponent<Renderer>()?t.GetComponent<Renderer>().bounds.ToString():""});}
